// pkgConfigOutput bounds both output and execution of a metadata query.
type pkgConfigOutput struct {
	data []byte
	err  error
	stop func()
}

func (b *pkgConfigOutput) Write(p []byte) (int, error) {
	if len(p) > (1<<20)-len(b.data) {
		b.err = fmt.Errorf("pkg-config output exceeds 1 MiB")
		if b.stop != nil {
			b.stop()
		}
		return 0, b.err
	}
	b.data = append(b.data, p...)
	return len(p), nil
}

func pkgConfigQuery(ctx context.Context, command string, env []string, args ...string) (string, error) {
	if command == "" {
		command = os.Getenv("PKG_CONFIG")
	}
	if command == "" {
		command = "pkg-config"
	}
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()
	cmd := exec.CommandContext(ctx, command, args...)
	cmd.Env = env
	cmd.WaitDelay = 100 * time.Millisecond
	var out, stderr pkgConfigOutput
	out.stop = func() { _ = cmd.Process.Kill() }
	stderr.stop = out.stop
	cmd.Stdout, cmd.Stderr = &out, &stderr
	if err := cmd.Run(); err != nil {
		if ctx.Err() != nil {
			err = ctx.Err()
		} else if out.err != nil {
			err = out.err
		} else if stderr.err != nil {
			err = stderr.err
		}
		return "", fmt.Errorf("pkg-config %s: %w: %s", strings.Join(args, " "), err, strings.TrimSpace(string(stderr.data)))
	}
	return strings.TrimRight(string(out.data), "\r\n"), nil
}

// pkgConfigSplit decodes shell-style words without evaluating them.
func pkgConfigSplit(s string) ([]string, error) {
	var words []string
	var word strings.Builder
	var quote rune
	escaped, started := false, false
	for _, r := range s {
		if escaped {
			if quote == '"' && r != '\\' && r != '"' && r != '$' && r != '`' && r != '\n' {
				word.WriteRune('\\')
			}
			if r != '\n' {
				word.WriteRune(r)
			}
			escaped = false
			started = true
			continue
		}
		if r == '\\' && quote != '\'' {
			escaped = true
			started = true
			continue
		}
		if quote != 0 {
			if r == quote {
				quote = 0
			} else {
				word.WriteRune(r)
			}
			continue
		}
		switch r {
		case '\'', '"':
			quote = r
			started = true
		case ' ', '\t', '\r', '\n':
			if started {
				words = append(words, word.String())
				word.Reset()
				started = false
			}
		default:
			word.WriteRune(r)
			started = true
		}
	}
	if escaped || quote != 0 {
		return nil, fmt.Errorf("unterminated pkg-config argument")
	}
	if started {
		words = append(words, word.String())
	}
	return words, nil
}

func pkgConfigValidate(packages []string) error {
	for _, pkg := range packages {
		if pkg == "" || pkg[0] == '-' {
			return fmt.Errorf("invalid pkg-config module %q", pkg)
		}
		for _, r := range pkg {
			if !(r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || strings.ContainsRune("._+-", r)) {
				return fmt.Errorf("invalid pkg-config module %q", pkg)
			}
		}
	}
	return nil
}

// pkgConfigDirectories finds absolute search directories, without interpreting
// linker library names or changing the process's loader search path.
func pkgConfigDirectories(packages []string) ([]string, string) {
	if len(packages) == 0 {
		return nil, ""
	}
	if err := pkgConfigValidate(packages); err != nil {
		return nil, err.Error()
	}
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	var dirs, diagnostics []string
	seen := make(map[string]bool)
	add := func(dir string) {
		if !filepath.IsAbs(dir) {
			return
		}
		dir = filepath.Clean(dir)
		if !seen[dir] {
			seen[dir] = true
			dirs = append(dirs, dir)
		}
	}
	for _, pkg := range packages {
		if ctx.Err() != nil {
			diagnostics = append(diagnostics, ctx.Err().Error())
			break
		}
		dir, err := pkgConfigQuery(ctx, "", nil, "--variable=libdir", pkg)
		if err != nil {
			diagnostics = append(diagnostics, err.Error())
		} else if dir != "" {
			add(dir)
		}
		out, err := pkgConfigQuery(ctx, "", nil, "--libs-only-L", pkg)
		if err != nil {
			diagnostics = append(diagnostics, err.Error())
			continue
		}
		flags, err := pkgConfigSplit(out)
		if err != nil {
			diagnostics = append(diagnostics, err.Error())
			continue
		}
		for i := 0; i < len(flags); i++ {
			if flags[i] == "-L" && i+1 < len(flags) {
				i++
				add(flags[i])
			} else if strings.HasPrefix(flags[i], "-L") {
				add(strings.TrimPrefix(flags[i], "-L"))
			}
		}
	}
	hint := ""
	if len(dirs) > 0 {
		hint = "pkg-config reports " + strings.Join(packages, ", ") + " in " + strings.Join(dirs, ", ")
	}
	if len(diagnostics) > 0 {
		if hint != "" {
			hint += "; "
		}
		hint += strings.Join(diagnostics, "; ")
	}
	return dirs, hint
}

func pkgConfigPaths(names, dirs []string) []string {
	var paths []string
	for _, dir := range dirs {
		for _, name := range names {
			if name != filepath.Base(name) {
				continue
			}
			paths = append(paths, filepath.Join(dir, name))
		}
	}
	return paths
}

// libraryNames returns the platform-specific shared library names to try.
func libraryNames() []string {
	switch runtime.GOOS {
	case "linux":
		return []string{"libdcgm.so.4"}
	default:
		return nil
	}
}

// register uses purego to bind a Go function pointer to a symbol in the dcgm
// library, recording whether the symbol resolved. Symbols absent from the
// loaded version are left unbound so the package still works against older
// releases; calling one returns *SymbolError rather than panicking.
func register(fn interface{}, symbol string) {
	if lib == 0 {
		return
	}
	sym, err := lookupLibrarySymbol(lib, symbol)
	if err != nil || sym == 0 {
		return
	}
	if !bindSymbol(fn, sym) {
		unbound[symbol] = errArgumentSlots
		return
	}
	present[symbol] = true
}

// registerSym resolves a symbol to its address and records whether it
// resolved. A symbol absent from the loaded version stays at zero, so
// calling it reports *SymbolError rather than jumping to address zero.
func registerSym(symbol string) uintptr {
	if lib == 0 {
		return 0
	}
	sym, err := lookupLibrarySymbol(lib, symbol)
	if err != nil || sym == 0 {
		return 0
	}
	present[symbol] = true
	return sym
}

// errArgumentSlots is the reason a symbol the library exports could still
// not be bound: the signature needs more argument registers and stack slots
// than this architecture's calling convention provides.
var errArgumentSlots = errors.New("signature needs more argument slots than this architecture provides")

// bindSymbol binds fn to the resolved symbol address sym and reports whether
// the binding succeeded. purego.RegisterFunc panics when it cannot build a
// trampoline for fn's signature; the usual cause is a signature needing more
// argument registers and stack slots than the target architecture allows
// (purego admits 32 arguments on 64-bit platforms, 15 on ppc64le). Recovering
// leaves such a symbol unbound, so calling it reports *SymbolError, rather
// than killing the process at load time.
//
// purego assigns to fn only after every check it can panic on, so a recovered
// binding leaves fn nil.
func bindSymbol(fn interface{}, sym uintptr) (ok bool) {
	defer func() {
		if recover() != nil {
			ok = false
		}
	}()
	purego.RegisterFunc(fn, sym)
	return true
}

// BindFailure names a symbol the loaded library exports but that could not
// be bound, and why.
type BindFailure struct {
	Symbol string
	Err    error
}

// BindFailures returns the symbols the loaded library exports that could
// not be bound, sorted by symbol name, or nil if every exported symbol
// bound. Calling one of these reports *SymbolError with the same Err.
//
// A load that reports no error can still leave symbols unbound: the
// library is fine and the signatures are not representable here. Call this
// after Load to find that out at once rather than one call site at a time.
// It does not trigger a load, and returns nil if none has happened.
func BindFailures() []BindFailure {
	loadMu.Lock()
	defer loadMu.Unlock()
	if len(unbound) == 0 {
		return nil
	}
	out := make([]BindFailure, 0, len(unbound))
	for sym, err := range unbound {
		out = append(out, BindFailure{Symbol: sym, Err: err})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Symbol < out[j].Symbol })
	return out
}

// ptrAdd advances a byte pointer by n bytes.
func ptrAdd(p *byte, n int) unsafe.Pointer {
	return unsafe.Add(unsafe.Pointer(p), n)
}

// checkLib loads the library if it has not been loaded yet and returns the
// load error, if any.
func checkLib() error {
	if ready.Load() {
		return nil
	}
	loadMu.Lock()
	defer loadMu.Unlock()
	return loadLocked("")
}

// checkLibSym loads the library if necessary and reports whether symbol is
// callable. It returns the load error if the library is unavailable, or
// *SymbolError if the library loaded but symbol is not callable.
func checkLibSym(symbol string) error {
	if err := checkLib(); err != nil {
		return err
	}
	if !present[symbol] {
		return &SymbolError{Symbol: symbol, Err: unbound[symbol]}
	}
	return nil
}

